    private val enAll by lazy { en + enExtra }
    private val arAll by lazy { ar + arExtra }

    fun text(context: Context, value: String): String {
        val language = context.getSharedPreferences("app", Context.MODE_PRIVATE).getString("language", "fr") ?: "fr"
        val table = when (language) { "en" -> enAll; "ar" -> arAll; else -> return value }
        table[value]?.let { return it }
        // Translate embedded phrases while preserving user data and calculated values.
        var result = value
        table.entries.sortedByDescending { it.key.length }.forEach { (source, target) ->
            if ((source.length > 3 || source == " h") && result.contains(source)) result = result.replace(source, target)
        }
        return result
    }
}
